function biggestTrianglePerimeter(sticks: number[]): number {
  const n = sticks.length;
  let best = 0;
  for (let i = 0; i < n; i++)
    for (let j = i + 1; j < n; j++)
      for (let k = j + 1; k < n; k++) {
        const [a, b, c] = [sticks[i], sticks[j], sticks[k]].sort((x, y) => x - y);
        if (a + b > c) best = Math.max(best, a + b + c);
      }
  return best;
}

