class Solution:
    def biggestTrianglePerimeter(self, sticks: List[int]) -> int:
        best = 0
        n = len(sticks)
        for i in range(n):
            for j in range(i + 1, n):
                for k in range(j + 1, n):
                    a, b, c = sorted((sticks[i], sticks[j], sticks[k]))
                    if a + b > c:
                        best = max(best, a + b + c)
        return best

