function biggestTrianglePerimeter(sticks: number[]): number {
  const s = [...sticks].sort((a, b) => b - a);
  for (let i = 0; i + 2 < s.length; i++) {
    if (s[i] < s[i + 1] + s[i + 2]) return s[i] + s[i + 1] + s[i + 2];
  }
  return 0;
}

